def gen(rng):
    def fmt(v):
        return str(len(v)) + '\n' + ' '.join(map(str, v))
    tests = [fmt([1]), fmt([0]), fmt([1, 2]), fmt([5, 5, 5]), fmt([-3, 9]), fmt([10**9, -10**9, 0])]
    for n in (3, 4, 5, 7, 10, 20, 40):
        tests.append(fmt([rng.randint(-100, 100) for _ in range(n)]))
        tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(min(n, 30))]))
    n = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)]))
    tests.append(fmt(list(range(1, n + 1))))
    tests.append(fmt([7] * n))
    tests.append(fmt([rng.randint(-5, 5) for _ in range(n)]))
    return tests
